style.css:
@-moz-document domain("clever.com") {
/* Soft pastel pink background for the whole page */
    body, html, #app, [class*="portal-container"] {
        background: linear-gradient(135deg, #ffe6f0, #f3e5f5, #e8f4f8) !important;
        font-family: 'Quicksand', 'Poppins', 'Comic Sans MS', sans-serif !important;
    }

    /* FORCED PINK TOP BAR (Targets standard headers and top-anchored elements) */
    header, nav, 
    [class*="header"], [class*="nav"], [class*="navbar"], 
    [class*="top"], [class*="banner"], [class*="bar"] {
        background-color: #ffb3c6 !important;
        background-image: none !important;
        border-bottom: 2px dashed #ffa6c1 !important;
    }

    /* Round out major containers and boxes */
    div, section, article {
        border-radius: 16px !important;
    }

    /* Style app tiles and buttons to look like cute little cards */
    a[class*="app"], button[class*="app"], div[class*="tile"], div[class*="card"] {
        background-color: rgba(255, 255, 255, 0.9) !important;
        border: 2px solid #ffccd5 !important;
        box-shadow: 0 6px 15px rgba(255, 182, 193, 0.3) !important;
        transition: transform 0.2s ease !important;
    }

    /* Playful hover effect */
    a[class*="app"]:hover, button[class*="app"]:hover, div[class*="tile"]:hover, div[class*="card"]:hover {
        transform: translateY(-4px) scale(1.02) !important;
        box-shadow: 0 10px 20px rgba(255, 105, 180, 0.4) !important;
    }

    /* Soften all text colors for a cozy look */
    h1, h2, h3, h4, span, p, a {
        color: #59405c !important;
    }

    /* Cute styling for search boxes */
    input[type="text"], input[type="search"] {
        background-color: #fff0f3 !important;
        border: 2px solid #ffb3c6 !important;
        border-radius: 20px !important;
        color: #59405c !important;
        padding-left: 12px !important;
    }
}
